<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstado, descargar, eliminar, guardar, listar, opciones } from '../services/comites'
import type { ComiteItem, ComiteMode, ComiteOptions } from '../interfaces/comites.interface'
const props=defineProps<{mode:ComiteMode}>()
const labels={comites:{title:'Comités',one:'comité',description:'Administra comités, integrantes y documentos de creación.'},reuniones:{title:'Reuniones',one:'reunión',description:'Programa reuniones y controla su atención y archivos.'},acuerdos:{title:'Acuerdos',one:'acuerdo',description:'Consulta, atiende y cierra los acuerdos generados en reuniones.'},tipos:{title:'Tipos de comité',one:'tipo de comité',description:'Mantén el catálogo de clasificación de comités.'}}
const copy=computed(()=>labels[props.mode]),items=ref<ComiteItem[]>([]),options=ref<ComiteOptions>({tipos:[],personas:[],comites:[]}),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),file=ref<File|null>(null)
const form=reactive({codigo:'',nombre:'',descripcion:'',fecha:'',tipo_id:0,comite_id:0,miembros:[] as number[]})
async function load(){loading.value=true;error.value='';try{items.value=await listar(props.mode,search.value)}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function init(){try{options.value=await opciones()}catch{}await load()}
function open(item?:ComiteItem){editing.value=item?.id||null;Object.assign(form,{codigo:item?.codigo||'',nombre:item?.nombre||'',descripcion:item?.descripcion||'',fecha:item?.fecha||'',tipo_id:options.value.tipos.find(x=>x.nombre===item?.tipo)?.id||0,comite_id:options.value.comites.find(x=>x.nombre===item?.comite)?.id||0,miembros:item?.miembros?.map(x=>x.id)||[]});file.value=null;modal.value=true}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null}
async function save(){if(!form.descripcion.trim()&&props.mode!=='tipos'){error.value='Ingrese una descripción.';return}if(props.mode==='tipos'&&!form.nombre.trim()){error.value='Ingrese el nombre del tipo.';return}saving.value=true;try{let data:FormData|Record<string,unknown>={...form};if(props.mode==='comites'){const d=new FormData();Object.entries(form).forEach(([key,value])=>Array.isArray(value)?value.forEach(v=>d.append(`${key}[]`,String(v))):d.append(key,String(value)));if(file.value)d.append('documento',file.value);data=d}await guardar(props.mode,editing.value,data);success.value=`${copy.value.one} guardado correctamente.`;modal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function remove(item:ComiteItem){if(!confirm(`¿Eliminar este ${copy.value.one}?`))return;try{await eliminar(props.mode,item.id);await load()}catch(cause){error.value=message(cause)}}
async function close(item:ComiteItem){const state=props.mode==='acuerdos'?'cerrado':'atendido';if(!confirm(`¿Marcar como ${state}?`))return;try{await cambiarEstado(props.mode,item.id,state);success.value='Estado actualizado correctamente.';await load()}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}
onMounted(init)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Institucional / Gestión de Comités / {{copy.title}}</nav><header class="hero"><div class="mark">GC</div><div><small>AURA · Gestión institucional</small><h1>{{copy.title}}</h1><p>{{copy.description}}</p></div><strong>{{items.length}} registros</strong><button @click="open()">+ Nuevo</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><input v-model.trim="search" :placeholder="`Buscar ${copy.one}…`" @keyup.enter="load"><button @click="load">Buscar</button><button class="clear" @click="search='';load()">Limpiar</button></section><div v-if="loading" class="empty">Cargando registros…</div><div v-else-if="!items.length" class="empty">No se encontraron registros.</div><section v-else class="cards"><article v-for="item in items" :key="item.id" :class="{closed:item.finalizado}"><header><span>#{{item.codigo||item.id}}</span><em>{{item.estado||(item.finalizado?'Finalizado':'Pendiente')}}</em></header><small>{{item.tipo||item.comite||copy.one}}</small><h2>{{item.nombre||item.descripcion}}</h2><p v-if="item.nombre">{{item.descripcion}}</p><dl><template v-if="item.fecha"><dt>Fecha</dt><dd>{{item.fecha}}</dd></template><template v-if="item.miembros?.length"><dt>Integrantes</dt><dd>{{item.miembros.length}}</dd></template><template v-if="item.archivos!==undefined"><dt>Archivos</dt><dd>{{item.archivos}}</dd></template><template v-if="item.acuerdos!==undefined"><dt>Acuerdos</dt><dd>{{item.acuerdos}}</dd></template></dl><footer><button @click="open(item)">Editar</button><button v-if="item.documento" @click="descargar(mode,item.id)">Documento</button><button v-if="(mode==='reuniones'||mode==='acuerdos')&&!item.finalizado" class="done" @click="close(item)">{{mode==='acuerdos'?'Cerrar':'Atender'}}</button><button class="delete" @click="remove(item)">Eliminar</button></footer></article></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>Gestión de Comités</small><h2>{{editing?'Editar':'Registrar'}} {{copy.one}}</h2></div><button type="button" @click="modal=false">×</button></header><label v-if="mode==='tipos'">Nombre *<input v-model.trim="form.nombre"></label><template v-else><label v-if="mode==='comites'">Código<input v-model.trim="form.codigo"></label><label v-if="mode==='comites'">Tipo de comité *<select v-model="form.tipo_id"><option :value="0" disabled>Seleccione</option><option v-for="type in options.tipos" :key="type.id" :value="type.id">{{type.nombre}}</option></select></label><label v-if="mode==='reuniones'">Comité *<select v-model="form.comite_id"><option :value="0" disabled>Seleccione</option><option v-for="committee in options.comites" :key="committee.id" :value="committee.id">{{committee.nombre}}</option></select></label><label>Fecha *<input v-model="form.fecha" type="date"></label></template><label>Descripción {{mode==='tipos'?'':'*'}}<textarea v-model.trim="form.descripcion" rows="3"/></label><label v-if="mode==='comites'">Integrantes<select v-model="form.miembros" multiple><option v-for="person in options.personas" :key="person.id" :value="person.id">{{person.nombre}}</option></select></label><label v-if="mode==='comites'">Documento de creación<input type="file" @change="pick"></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#7257c8;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.7rem;font-weight:700}.hero small,.modal small,.cards small{color:var(--accent);font-size:.56rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.35rem}.hero p{margin:0;color:#7d898f;font-size:.7rem}.hero strong{margin-left:auto;font-size:.62rem}.hero button,.filters button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.59rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.65rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:15px;padding:12px;display:flex;gap:7px;border:1px solid #e0e5e8;border-radius:9px;background:#fff}.filters input{flex:1}.clear{color:#68757c!important;background:#edf1f3!important}.cards{margin-top:14px;display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.cards article{padding:14px;border:1px solid #e0e5e8;border-top:4px solid #d1c9eb;border-radius:9px;background:#fff}.cards article.closed{border-top-color:#36a577}.cards article>header{display:flex}.cards article>header span{font-size:.57rem;font-weight:700}.cards article>header em{margin-left:auto;padding:4px 7px;border-radius:10px;color:var(--accent);background:#eeeafa;font-size:.49rem;font-style:normal;text-transform:uppercase}.cards h2{margin:5px 0;font-size:.73rem}.cards p{color:#7d898f;font-size:.57rem}.cards dl{display:flex;gap:12px}.cards dt,.cards dd{margin:0;font-size:.52rem}.cards dt{color:#89949a}.cards footer{display:flex;gap:4px}.cards footer button{padding:5px;border:0;color:var(--accent);background:none;font-size:.54rem}.cards footer .done{color:#287153}.cards footer .delete{margin-left:auto;color:#b44747}.empty{margin-top:14px;padding:50px;text-align:center;border:1px dashed #ccd5da;border-radius:9px;background:#fff;font-size:.68rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,520px);max-height:90vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0 15px;font-size:1rem}.modal header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:11px;font-size:.61rem}input,select,textarea{width:100%;margin-top:4px;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.65rem}.modal select[multiple]{min-height:100px}.modal footer{display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.cards{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}
</style>
